const body = $input.first().json.body || {};

const SYSTEM = "You are 'My Space assistant', a study assistant for a computer engineering student at the Hashemite University (Jordan). Reply in Jordanian Arabic dialect, short and clear, answer directly. Rely ONLY on the student data JSON provided; never invent data — if something is not there, say it is not recorded. You may propose app actions that run after the student confirms: put them at the very end exactly as <actions>[...]</actions> JSON. Allowed types only: {type:'task',title,due:'YYYY-MM-DD',course,priority:'high'|'normal'}, {type:'exam',name,course,date:'YYYY-MM-DD',time:'HH:MM'}, {type:'expense',amount,category,note}, {type:'done',id}, {type:'go',view:'today|timetable|tasks|grades|courses|exams|attendance|budget|timer|plan|tree|gpa|stats|prayer|campus|settings'}. Only propose actions when the student asks to add/change something. Use simple Markdown (bold, lists).";

const q = String(body.question == null ? '' : body.question).trim().slice(0, 800);
if (!q) {
  throw new Error('Question is empty');
}

let context = body.context == null ? '' : body.context;
if (typeof context !== 'string') {
  context = JSON.stringify(context);
}
context = context.slice(0, 14000);

const history = Array.isArray(body.history) ? body.history.slice(-8) : [];
const contents = history
  .filter(h => h && h.content != null && String(h.content).trim() !== '')
  .map(h => ({
    role: h.role === 'assistant' ? 'model' : 'user',
    parts: [{ text: String(h.content).slice(0, 1500) }],
  }));
contents.push({ role: 'user', parts: [{ text: q }] });

return [{
  json: {
    model: /^gemini-[a-z0-9.-]{3,40}$/.test(String(body.model || '')) ? body.model : 'gemini-flash-latest',
    request: {
      systemInstruction: { parts: [{ text: SYSTEM + '\n\nStudent data now:\n' + context }] },
      contents,
      generationConfig: { temperature: 0.4, maxOutputTokens: 1000 },
    },
  },
}];

const res = $input.first().json;
const statusCode = Number(res.statusCode) || 0;
let body = res.body;
if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch (e) { body = { raw: body }; }
}
body = body || {};

const parts = (((body.candidates || [])[0] || {}).content || {}).parts || [];
const answer = parts
  .map(p => (p && typeof p.text === 'string') ? p.text : '')
  .join('')
  .trim();

if (statusCode >= 300 || !answer) {
  const message = (body.error && body.error.message) ? body.error.message : 'Gemini returned no reply';
  return [{ json: { status: statusCode >= 300 ? statusCode : 502, body: { error: message } } }];
}

return [{ json: { status: 200, body: { answer } } }];

const body = $input.first().json.body || {};

const ALLOWED = ['gemini-flash-latest', 'gemini-3.5-flash', 'gemini-2.5-flash', 'gemini-2.5-flash-lite', 'gemini-2.0-flash', 'gemini-flash-lite-latest'];
/* أي نموذج Gemini بالاسم (القائمة القديمة كانت تتقادم كل ما Google توقف نموذج) */
const model = (ALLOWED.includes(body.model) || /^gemini-[a-z0-9.-]{3,40}$/.test(String(body.model || ''))) ? body.model : 'gemini-flash-latest';

const request = body.request;
if (!request || typeof request !== 'object' || !Array.isArray(request.contents) || request.contents.length === 0) {
  throw new Error('request.contents is missing or empty');
}
if (JSON.stringify(request).length > 9000000) {
  throw new Error('Request is too large (max 9,000,000 characters)');
}

return [{ json: { model, request } }];
